// /docs/reasoning/changelog — autogenerated changelog for the AbarVa
// reasoning layer.
//
// Server component. Reads the JSON fixture at
// `@/lib/reasoning/generated/changelog.json`, which is produced by
// `scripts/generate-reasoning-changelog.ts` from the git log filtered
// to `(reasoning)`-scoped commits. No runtime git invocation, no LLM,
// no curated prose — this is the deterministic git-derived view.
//
// Filtering is done client-side in a small "use client" island so the
// page stays statically renderable.

import type { CSSProperties, ReactNode } from 'react';
import Link from 'next/link';
import { COLORS, RADIUS, SPACING, TYPOGRAPHY } from '@/lib/design/design-tokens';
import { AdminCanonShellV2 } from '@/components/admin/AdminCanonShellV2';
import { EditorialCanvas } from '@/components/admin/EditorialCanvas';
import { AgentRail } from '@/components/admin/AgentRail';
import changelogJson from '@/lib/reasoning/generated/changelog.json';
import type {
  ReasoningChangelog,
  ReasoningCommitEntry,
  ReasoningCommitKind,
} from '@/lib/reasoning/changelog-parser';
import { ChangelogList } from './ChangelogList';

export const metadata = {
  title: 'Reasoning changelog · AbarVa Docs',
};

const COLUMN_MAX_WIDTH = '720px';

const SECTION_STYLE: CSSProperties = {
  background: COLORS.white,
  border: `1px solid ${COLORS.ink}14`,
  borderRadius: RADIUS.lg,
  padding: SPACING.xl,
  maxWidth: COLUMN_MAX_WIDTH,
  width: '100%',
};

const H2_STYLE: CSSProperties = {
  fontFamily: TYPOGRAPHY.serif,
  fontSize: 26,
  fontWeight: 600,
  color: COLORS.ink,
  margin: 0,
  letterSpacing: '-0.01em',
  lineHeight: 1.2,
};

const H3_STYLE: CSSProperties = {
  fontFamily: TYPOGRAPHY.sans,
  fontSize: 13,
  fontWeight: 600,
  color: COLORS.navy,
  margin: 0,
  textTransform: 'uppercase',
  letterSpacing: '0.08em',
};

const PROSE_STYLE: CSSProperties = {
  fontFamily: TYPOGRAPHY.sans,
  fontSize: 15,
  lineHeight: 1.65,
  color: `${COLORS.ink}cc`,
  margin: 0,
};

const META_STYLE: CSSProperties = {
  fontFamily: TYPOGRAPHY.mono,
  fontSize: 12,
  color: `${COLORS.ink}88`,
  margin: 0,
};

const LINK_STYLE: CSSProperties = {
  color: COLORS.navy,
  textDecoration: 'underline',
  textUnderlineOffset: '2px',
};

function Section({
  eyebrow,
  title,
  children,
}: {
  eyebrow: string;
  title: string;
  children: ReactNode;
}) {
  return (
    <section style={SECTION_STYLE}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: SPACING.md }}>
        <h3 style={H3_STYLE}>{eyebrow}</h3>
        <h2 style={H2_STYLE}>{title}</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: SPACING.md }}>
          {children}
        </div>
      </div>
    </section>
  );
}

function formatGeneratedAt(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toUTCString();
}

function countByKind(entries: ReadonlyArray<ReasoningCommitEntry>): Record<ReasoningCommitKind, number> {
  const counts: Record<ReasoningCommitKind, number> = {
    feat: 0,
    fix: 0,
    refactor: 0,
    docs: 0,
    chore: 0,
  };
  for (const e of entries) counts[e.kind] += 1;
  return counts;
}

export default function ReasoningChangelogDocPage() {
  const data = changelogJson as ReasoningChangelog;
  const counts = countByKind(data.entries);

  return (
    <AdminCanonShellV2
      agentRail={
        <AgentRail
          primaryAgentLabel="Steward"
          primaryActionLabel="Open architecture doc"
          primaryActionHref="/docs/reasoning"
        />
      }
    >
      <EditorialCanvas
        eyebrow="Docs · Reasoning"
        title="Reasoning layer · changelog"
        subtitle="An autogenerated, git-derived view of every commit shipped against the AbarVa reasoning layer. Regenerated by running scripts/generate-reasoning-changelog.ts and committing the resulting JSON."
      >
        <Section eyebrow="Generated" title="Snapshot">
          <p style={META_STYLE}>
            generated-at: {formatGeneratedAt(data.generatedAt)}
          </p>
          <p style={META_STYLE}>
            entries: {data.entries.length} (feat: {counts.feat}, fix: {counts.fix},
            refactor: {counts.refactor}, docs: {counts.docs}, chore: {counts.chore})
          </p>
          <p style={PROSE_STYLE}>
            This page is a flat, deterministic view of the git log
            filtered to <code style={{ fontFamily: TYPOGRAPHY.mono }}>(reasoning)</code>-scoped commits. For the
            architectural narrative, read the{' '}
            <Link href="/docs/reasoning" style={LINK_STYLE}>
              architecture doc
            </Link>
            ; for an SDK-style walkthrough, read the{' '}
            <Link href="/docs/reasoning/quickstart" style={LINK_STYLE}>
              quickstart
            </Link>
            ; for a per-export TypeScript reference, read the{' '}
            <Link href="/docs/reasoning/api" style={LINK_STYLE}>
              API reference
            </Link>
            ; for a hands-on, click-through tour of the live product surfaces
            wired through Layer 3, read the{' '}
            <Link href="/docs/reasoning/demo" style={LINK_STYLE}>
              5-minute demo walkthrough
            </Link>
            .
          </p>
        </Section>

        <Section eyebrow="Entries" title="Commits, newest first">
          <ChangelogList entries={data.entries} counts={counts} />
        </Section>
      </EditorialCanvas>
    </AdminCanonShellV2>
  );
}
